 function modal(title,body){if(q('#h-dialog').open&&H.dirty&&!H.busy&&!confirm('Đóng cửa sổ đang mở?'))return;H.dirty=false;q('#h-modal-title').textContent=title;q('#h-modal-body').innerHTML=body+'<div id="h-modal-message" role="status" aria-live="polite"></div>';if(!q('#h-dialog').open)q('#h-dialog').showModal();}
